script:
data = json.decode(repo.read("deploy.json"))

prod = []
for t in data.get("targets", []):
    if t.get("env") == "prod":
        prod.append(t)

names = sorted([t["name"] for t in prod])
total = 0
for t in prod:
    total += t.get("replicas", 0)

overrides_present = repo.read("overrides.json", missing_ok=True) != None

result({
    "prod_targets": names,
    "total_replicas": total,
    "overrides_json_present": overrides_present,
})
